    <style>
      :root {
        color-scheme: light;
        --page-bg: #f4f7fb;
        --surface: #ffffff;
        --text: #142033;
        --muted: #526173;
        --border: #c7d2e0;
        --accent: #225ee8;
        --accent-strong: #1747b8;
        --accent-soft: #e8efff;
        --error: #b42318;
        --success: #067647;
        --shadow: 0 24px 60px #bcc7d8;
      }

      * {
        box-sizing: border-box;
      }

      body {
        min-width: 320px;
        margin: 0;
        font-family:
          Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
          "Segoe UI", sans-serif;
        line-height: 1.5;
        color: var(--text);
        background:
          radial-gradient(circle at top left, #dbe8ff 0, transparent 34rem),
          var(--page-bg);
      }

      .skip-link {
        position: absolute;
        left: 1rem;
        top: 1rem;
        z-index: 10;
        transform: translateY(-150%);
        padding: 0.75rem 1rem;
        border-radius: 999px;
        color: #ffffff;
        background: var(--accent);
        font-weight: 700;
      }

      .skip-link:focus {
        transform: translateY(0);
        outline: 3px solid #0f1f3d;
        outline-offset: 3px;
      }

