        margin: 0 0 0.75rem;
        color: var(--accent);
        font-size: 0.875rem;
        font-weight: 800;
        letter-spacing: 0.08em;
        text-transform: uppercase;
      }

      h1 {
        margin: 0;
        font-size: clamp(2rem, 8vw, 3.5rem);
        line-height: 1.05;
        letter-spacing: -0.05em;
      }

      .intro {
        max-width: 34rem;
        margin: 1rem 0 2rem;
        color: var(--muted);
        font-size: 1.0625rem;
      }

      form {
        display: grid;
        gap: 1.5rem;
      }

      .form-field {
        display: grid;
        gap: 0.9rem;
      }

      fieldset {
        min-width: 0;
