        margin-bottom: 0.75rem;
        color: var(--text);
        font-size: 1.125rem;
        font-weight: 800;
      }

      .required {
        color: var(--error);
      }

      .hint,
      .message {
        margin: 0;
        color: var(--muted);
        font-size: 0.95rem;
      }

      .radio-options {
        display: grid;
        gap: 0.75rem;
      }

