    <style>
      :root {
        color-scheme: light;
        --page-bg: #f4f7fb;
        --surface: #ffffff;
        --text: #142033;
        --muted: #526173;
        --border: #c7d2e0;
        --accent: #225ee8;
        --accent-strong: #1747b8;
        --accent-soft: #e8efff;
        --error: #b42318;
        --success: #067647;
        --shadow: 0 24px 60px #bcc7d8;
      }

      * {
        box-sizing: border-box;
      }

      body {
        min-width: 320px;
        margin: 0;
        font-family:
          Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
          "Segoe UI", sans-serif;
        line-height: 1.5;
        color: var(--text);
        background:
          radial-gradient(circle at top left, #dbe8ff 0, transparent 34rem),
          var(--page-bg);
      }

      .skip-link {
        position: absolute;
        left: 1rem;
        top: 1rem;
        z-index: 10;
        transform: translateY(-150%);
        padding: 0.75rem 1rem;
        border-radius: 999px;
        color: #ffffff;
        background: var(--accent);
        font-weight: 700;
      }

      .skip-link:focus {
        transform: translateY(0);
        outline: 3px solid #0f1f3d;
        outline-offset: 3px;
      }

      main {
        display: grid;
        min-height: 100vh;
        place-items: center;
        padding: 2rem 1rem;
      }

      .card {
        width: min(100%, 42rem);
        padding: clamp(1.5rem, 5vw, 3rem);
        border: 1px solid var(--border);
        border-radius: 1.5rem;
        background: var(--surface);
        box-shadow: var(--shadow);
      }

      .eyebrow {
        margin: 0 0 0.75rem;
        color: var(--accent);
        font-size: 0.875rem;
        font-weight: 800;
        letter-spacing: 0.08em;
        text-transform: uppercase;
      }

      h1 {
        margin: 0;
        font-size: clamp(2rem, 8vw, 3.5rem);
        line-height: 1.05;
        letter-spacing: -0.05em;
      }

      .intro {
        max-width: 34rem;
        margin: 1rem 0 2rem;
        color: var(--muted);
        font-size: 1.0625rem;
      }

      form {
        display: grid;
        gap: 1.5rem;
      }

      .form-field {
        display: grid;
        gap: 0.9rem;
      }

      fieldset {
        min-width: 0;
        margin: 0;
        padding: 0;
        border: 0;
      }

      legend {
        margin-bottom: 0.75rem;
        color: var(--text);
        font-size: 1.125rem;
        font-weight: 800;
      }

      .required {
        color: var(--error);
      }

      .hint,
      .message {
        margin: 0;
        color: var(--muted);
        font-size: 0.95rem;
      }

      .radio-options {
        display: grid;
        gap: 0.75rem;
      }

      .radio-option {
        display: flex;
        align-items: center;
        gap: 0.875rem;
        min-width: 0;
        padding: 1rem;
        border: 2px solid var(--border);
        border-radius: 1rem;
        background: var(--surface);
        cursor: pointer;
        transition:
          border-color 160ms ease,
          background-color 160ms ease,
          transform 160ms ease;
      }

      .radio-option:hover {
        border-color: var(--accent);
        background: var(--accent-soft);
      }

      .radio-option:has(input:checked) {
        border-color: var(--accent);
        background: var(--accent-soft);
      }

      .radio-option:has(input:focus-visible) {
        outline: 3px solid var(--accent);
        outline-offset: 3px;
      }

      input[type="radio"] {
        width: 1.25rem;
        height: 1.25rem;
        margin: 0;
        accent-color: var(--accent);
        flex: 0 0 auto;
      }

      .option-text {
        min-width: 0;
        font-weight: 700;
        overflow-wrap: anywhere;
      }

      button {
        width: fit-content;
        min-width: 9rem;
        min-height: 3rem;
        border: 0;
        border-radius: 999px;
        padding: 0.875rem 1.5rem;
        color: #ffffff;
        background: var(--accent);
        font: inherit;
        font-weight: 800;
        cursor: pointer;
        transition:
          background-color 160ms ease,
          transform 160ms ease;
      }

      button:hover {
        background: var(--accent-strong);
      }

      button:active {
        transform: translateY(1px);
      }

      button:focus-visible {
        outline: 3px solid var(--accent-strong);
        outline-offset: 3px;
      }

      .message {
        min-height: 1.5rem;
        font-weight: 700;
      }

      .message.error {
        color: var(--error);
      }

      .message.success {
        color: var(--success);
      }

      @media (max-width: 30rem) {
        button {
          width: 100%;
        }
      }

      @media (prefers-reduced-motion: reduce) {
        *,
        *::before,
        *::after {
          scroll-behavior: auto !important;
          transition-duration: 0.01ms !important;
          animation-duration: 0.01ms !important;
          animation-iteration-count: 1 !important;
        }
      }

      @media (forced-colors: active) {
        .card,
        .radio-option {
          border-color: ButtonBorder;
          box-shadow: none;
        }

        .radio-option:has(input:checked),
        .radio-option:hover {
          border-color: Highlight;
        }

        button,
        .skip-link {
          border: 2px solid ButtonBorder;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>

    <main id="main-content">
      <section class="card" aria-labelledby="page-title">
        <p class="eyebrow">Preferences</p>
        <h1 id="page-title">Choose your notification style</h1>
        <p class="intro">
          Select the channel that works best for timely product updates and
          account alerts.
        </p>

        <form id="notification-form" novalidate>
          <div class="form-field">
            <fieldset aria-describedby="notification-hint notification-message">
              <legend>
                How do you prefer to receive notifications?
                <span class="required" aria-hidden="true">*</span>
              </legend>
              <p class="hint" id="notification-hint">Choose one option.</p>

              <div class="radio-options">
                <label class="radio-option" for="notification-email">
                  <input
                    type="radio"
                    id="notification-email"
                    name="notificationPreference"
                    value="Email"
                    required
                  >
                  <span class="option-text">Email</span>
                </label>

                <label class="radio-option" for="notification-sms">
                  <input
                    type="radio"
                    id="notification-sms"
                    name="notificationPreference"
                    value="SMS"
                    required
                  >
                  <span class="option-text">SMS</span>
                </label>

                <label class="radio-option" for="notification-push">
                  <input
                    type="radio"
                    id="notification-push"
                    name="notificationPreference"
                    value="Push Notifications"
                    required
                  >
                  <span class="option-text">Push Notifications</span>
                </label>
              </div>
            </fieldset>
          </div>

          <button type="submit">Submit</button>
          <p class="message" id="notification-message" aria-live="polite"></p>
        </form>
      </section>
    </main>

    <script>
      const form = document.querySelector("#notification-form");
      const message = document.querySelector("#notification-message");
      const radios = Array.from(
        document.querySelectorAll('input[name="notificationPreference"]')
      );

      function setRadioInvalidState(isInvalid) {
        radios.forEach((radio) => {
          radio.setAttribute("aria-invalid", String(isInvalid));
        });
      }

      radios.forEach((radio) => {
        radio.addEventListener("change", () => {
          setRadioInvalidState(false);
          message.textContent = "";
          message.className = "message";
        });
      });

      form.addEventListener("submit", (event) => {
        event.preventDefault();

        const selected = radios.find((radio) => radio.checked);

        if (!selected) {
          setRadioInvalidState(true);
          message.textContent =
            "Please choose Email, SMS, or Push Notifications before submitting.";
          message.className = "message error";
          radios[0].focus();
          return;
        }

        setRadioInvalidState(false);
        message.textContent = `Preference saved: ${selected.value}.`;
        message.className = "message success";
      });
    </script>
  </body>
</html>
